<?php $title='Modul Pembelajaran';$page='modules';$pdo=Database::connection();$uid=current_user()['id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$q=$pdo->prepare('INSERT INTO modules(teacher_id,class_id,subject_id,title,description) VALUES(?,?,?,?,?)');$q->execute([$uid,(int)$_POST['class_id'],(int)$_POST['subject_id'],trim($_POST['title']),trim($_POST['description'])]);flash('success','Modul berhasil dibuat.');redirect('modules');}$classes=$pdo->query('SELECT * FROM classes ORDER BY name')->fetchAll();$subjects=$pdo->query('SELECT * FROM subjects ORDER BY name')->fetchAll();$q=$pdo->prepare('SELECT m.*,c.name class_name,s.name subject_name FROM modules m JOIN classes c ON c.id=m.class_id JOIN subjects s ON s.id=m.subject_id WHERE m.teacher_id=? ORDER BY m.created_at DESC');$q->execute([$uid]);$rows=$q->fetchAll();require __DIR__.'/../_dashboard_start.php'; ?>
<div class="page-heading"><div><h1>Modul Pembelajaran</h1><p>Buat dan kelola ruang belajar untuk kelas yang Anda ampu.</p></div></div><section class="panel"><h3>Buat Modul Baru</h3><form method="post" class="form-grid four"><?= csrf_field() ?><label>Judul Modul<input name="title" required></label><label>Kelas<select name="class_id"><?php foreach($classes as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label>Mata Pelajaran<select name="subject_id"><?php foreach($subjects as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></label><label>Deskripsi<input name="description"></label><button class="btn btn-primary">Buat Modul</button></form></section><section class="card-grid"><?php foreach($rows as $r): ?><article class="course-card"><div class="course-icon"><i class="fa-solid fa-server"></i></div><span><?= e($r['class_name']) ?> · <?= e($r['subject_name']) ?></span><h3><?= e($r['title']) ?></h3><p><?= e($r['description']) ?></p><a href="<?= e(url('materials&module='.$r['id'])) ?>">Kelola materi →</a></article><?php endforeach; ?></section><?php require __DIR__.'/../_dashboard_end.php'; ?>